import hmac
import hashlib
import json
import base64
import time
import os
import sys
import unicodedata
from flask import Flask, request, jsonify, abort
from functools import wraps

app = Flask(__name__)

# Configuration
SECRET_KEY = os.environ.get('JWT_SECRET', os.urandom(32).hex())
TOKEN_EXPIRY = 3600  # 1 hour
MAX_USERNAME_LEN = 64
MAX_PASSWORD_LEN = 128

# In-memory user store (production would use a database)
USER_DB = {}
SESSION_STORE = {}

def _normalize_input(value):
    """Normalize unicode input to prevent homoglyph attacks.
    Uses NFKC normalization as recommended by OWASP."""
    if not isinstance(value, str):
        value = str(value)
    return unicodedata.normalize('NFKC', value)

def _compute_signature(header_b64, payload_b64, secret):
    """Compute HMAC-SHA256 signature for JWT."""
    message = f"{header_b64}.{payload_b64}"
    # Use raw secret bytes - do not normalize cryptographic key material
    if isinstance(secret, str):
        secret_bytes = secret.encode('utf-8')
    else:
        secret_bytes = secret
    return hmac.new(
        secret_bytes,
        message.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

def _b64_encode(data):
    """URL-safe base64 encode without padding."""
    return base64.urlsafe_b64encode(
        json.dumps(data, separators=(',', ':')).encode('utf-8')
    ).rstrip(b'=').decode('ascii')

def _b64_decode(s):
    """URL-safe base64 decode with padding restoration."""
    # Add padding back
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return json.loads(base64.urlsafe_b64decode(s.encode('ascii')))

def create_token(user_id, role='user'):
    """Create a signed JWT token."""
    header = {'alg': 'HS256', 'typ': 'JWT'}
    payload = {
        'sub': user_id,
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + TOKEN_EXPIRY
    }
    header_b64 = _b64_encode(header)
    payload_b64 = _b64_encode(payload)
    signature = _compute_signature(header_b64, payload_b64, SECRET_KEY)
    return f"{header_b64}.{payload_b64}.{signature}"

def verify_token(token):
    """Verify JWT token signature and expiration."""
    parts = token.split('.')
    if len(parts) != 3:
        return None

    header_b64, payload_b64, provided_sig = parts

    # Decode and validate header
    try:
        header = _b64_decode(header_b64)
    except (json.JSONDecodeError, Exception):
        return None

    # Enforce algorithm - prevent algorithm confusion attacks
    if header.get('alg') != 'HS256':
        return None
    if header.get('typ') != 'JWT':
        return None

    # Compute expected signature
    expected_sig = _compute_signature(header_b64, payload_b64, SECRET_KEY)

    # Constant-time comparison to prevent timing attacks
    if not hmac.compare_digest(
        provided_sig.encode('utf-8'),
        expected_sig.encode('utf-8')
    ):
        return None

    # Decode payload and check expiration
    try:
        payload = _b64_decode(payload_b64)
    except (json.JSONDecodeError, Exception):
        return None

    if payload.get('exp', 0) < time.time():
        return None

    return payload

def require_auth(f):
    """Decorator to require valid JWT authentication."""
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        payload = verify_token(token)
        if payload is None:
            abort(401)
        request.user = payload
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    """Decorator to require admin role."""
    @wraps(f)
    def decorated(*args, **kwargs):
        if getattr(request, 'user', {}).get('role') != 'admin':
            abort(403)
        return f(*args, **kwargs)
    return decorated

def _hash_password(password, salt=None):
    """Hash password with PBKDF2-HMAC-SHA256."""
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return salt + dk

def _verify_password(password, stored_hash):
    """Verify password against stored hash."""
    salt = stored_hash[:16]
    expected = _hash_password(password, salt)
    return hmac.compare_digest(stored_hash, expected)

@app.route('/api/register', methods=['POST'])
def register():
    """Register a new user account."""
    data = request.get_json(force=False, silent=True)
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    # Input validation
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'Invalid input types'}), 400

    # Normalize username to prevent homoglyph registration attacks
    username = _normalize_input(username)

    if len(username) < 3 or len(username) > MAX_USERNAME_LEN:
        return jsonify({'error': 'Username must be 3-64 characters'}), 400
    if len(password) < 8 or len(password) > MAX_PASSWORD_LEN:
        return jsonify({'error': 'Password must be 8-128 characters'}), 400
    if not username.isalnum():
        return jsonify({'error': 'Username must be alphanumeric'}), 400

    if username in USER_DB:
        return jsonify({'error': 'Username already exists'}), 409

    USER_DB[username] = {
        'password_hash': _hash_password(password),
        'role': 'user',
        'created_at': int(time.time())
    }

    return jsonify({'message': 'User registered successfully'}), 201

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user and return JWT token."""
    data = request.get_json(force=False, silent=True)
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'Invalid input types'}), 400

    # Normalize username for lookup consistency
    username = _normalize_input(username)

    user = USER_DB.get(username)
    if user is None:
        # Constant-time fake check to prevent user enumeration
        _hash_password('dummy_password_for_timing')
        return jsonify({'error': 'Invalid credentials'}), 401

    if not _verify_password(password, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = create_token(username, user['role'])
    return jsonify({'token': token, 'expires_in': TOKEN_EXPIRY}), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    """Get current user's profile."""
    username = request.user.get('sub', '')
    user = USER_DB.get(username)
    if not user:
        abort(404)
    return jsonify({
        'username': username,
        'role': user['role'],
        'created_at': user['created_at']
    })

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_users():
    """Admin endpoint to list all users."""
    users = []
    for uname, udata in USER_DB.items():
        users.append({
            'username': uname,
            'role': udata['role'],
            'created_at': udata['created_at']
        })
    return jsonify({'users': users})

@app.route('/api/admin/promote', methods=['POST'])
@require_auth
@require_admin
def promote_user():
    """Admin endpoint to promote a user to admin."""
    data = request.get_json(force=False, silent=True)
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    target = _normalize_input(data.get('username', ''))
    if target not in USER_DB:
        return jsonify({'error': 'User not found'}), 404

    USER_DB[target]['role'] = 'admin'
    return jsonify({'message': f'{target} promoted to admin'}), 200

if __name__ == '__main__':
    # Create default admin account.
    # Require an explicit admin password; fail closed if it is not provided
    # to avoid shipping a hardcoded/default credential (CWE-798).
    admin_password = os.environ.get('ADMIN_PASSWORD')
    if not admin_password:
        sys.stderr.write(
            'ERROR: ADMIN_PASSWORD environment variable must be set to a '
            'strong, unique value before starting the server.\n'
        )
        sys.exit(1)
    if len(admin_password) < 8 or len(admin_password) > MAX_PASSWORD_LEN:
        sys.stderr.write(
            'ERROR: ADMIN_PASSWORD must be 8-128 characters.\n'
        )
        sys.exit(1)

    USER_DB['admin'] = {
        'password_hash': _hash_password(admin_password),
        'role': 'admin',
        'created_at': int(time.time())
    }
    app.run(host='127.0.0.1', port=5000, debug=False)
